    31	    private final JsonMapper mapper;
    32	    private final HttpClient http;
    33	
    34	    public TranslogCarrier(@Value("${translog.url:}") String baseUrl,
    35	            @Value("${translog.timeout:2s}") Duration timeout, JsonMapper mapper) {
    36	        this.baseUrl = baseUrl.strip().replaceAll("/+$", "");
    37	        this.timeout = timeout;
    38	        this.mapper = mapper;
    39	        this.http = HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).connectTimeout(timeout).build();
    40	    }
    41	
    42	    @Override
    43	    public CarrierQuote quote(String zipCode, int weightGrams, CarrierService service) {
    44	        if (baseUrl.isEmpty()) {
    45	            throw new CarrierUnavailableException("TRANSLOG_URL não configurada");
    46	        }
    47	        URI uri;
    48	        try {
    49	            uri = URI.create(baseUrl + "/v2/quote"
    50	                    + "?zip=" + URLEncoder.encode(zipCode, StandardCharsets.UTF_8)
    51	                    + "&weight_g=" + weightGrams
    52	                    + "&service=" + serviceCode(service));
    53	        } catch (IllegalArgumentException e) {
    54	            throw new CarrierUnavailableException("TRANSLOG_URL inválida", e);
    55	        }
    56	        HttpResponse<String> response = get(uri);
    57	        if (response.statusCode() != 200) {
    58	            throw new CarrierUnavailableException("TransLog respondeu " + response.statusCode());
    59	        }
    60	        return parse(response.body());
    61	    }
    62	
    63	    private HttpResponse<String> get(URI uri) {
    64	        CompletableFuture<HttpResponse<String>> call;
    65	        try {
    66	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(timeout).GET().build();
    67	            call = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
    68	        } catch (IllegalArgumentException e) {
    69	            throw new CarrierUnavailableException("TRANSLOG_URL inválida", e);
    70	        }
    71	        try {
    72	            // O prazo vale para a resposta inteira, não só para a conexão.
    73	            return call.get(timeout.toMillis(), TimeUnit.MILLISECONDS);
    74	        } catch (TimeoutException e) {
    75	            call.cancel(true);
    76	            throw new CarrierUnavailableException("TransLog não respondeu a tempo", e);
    77	        } catch (ExecutionException e) {
    78	            throw new CarrierUnavailableException("Falha ao chamar a TransLog", e.getCause());
    79	        } catch (InterruptedException e) {
    80	            Thread.currentThread().interrupt();
    81	            call.cancel(true);
    82	            throw new CarrierUnavailableException("Chamada à TransLog interrompida", e);
    83	        }
    84	    }
    85	
    86	    private CarrierQuote parse(String body) {
    87	        JsonNode json;
    88	        try {
    89	            json = mapper.readTree(body);
    90	        } catch (JacksonException e) {
    91	            throw new CarrierUnavailableException("Resposta inválida da TransLog", e);
    92	        }
    93	        if (json == null || !json.isObject()) {
    94	            throw new CarrierUnavailableException("Resposta inválida da TransLog");
    95	        }
    96	        if (json.has("error")) {
    97	            JsonNode error = json.get("error");
    98	            if (error.isString() && ZIP_NOT_SERVED.equals(error.stringValue())) {
    99	                throw new ZipNotServedException();
   100	            }
   101	            throw new CarrierUnavailableException("TransLog respondeu erro " + error);
   102	        }
   103	        JsonNode cents = json.path("price_cents");
   104	        JsonNode hours = json.path("eta_hours");
   105	        if (!isNonNegativeInt(cents) || !isNonNegativeInt(hours)) {
   106	            throw new CarrierUnavailableException("Resposta incompleta da TransLog");
   107	        }
   108	        return new CarrierQuote(BigDecimal.valueOf(cents.asLong(), 2), hours.asInt());
   109	    }
   110	
   111	    private static boolean isNonNegativeInt(JsonNode node) {
   112	        return node.isNumber() && node.canConvertToExactIntegral() && node.canConvertToInt() && node.asInt() >= 0;
   113	    }
   114	
   115	    private static String serviceCode(CarrierService service) {
   116	        return switch (service) {
   117	            case STANDARD -> "STD";
   118	            case EXPRESS -> "EXP";
   119	        };
   120	    }
   121	}
