    43	record JdbcUrl(String url, String user, String password) {
    44	
    45	    static JdbcUrl parse(String raw) {
    46	        String value = raw.strip();
    47	        if (value.startsWith("jdbc:")) {
    48	            return new JdbcUrl(value, null, null);
    49	        }
    50	        if (!value.startsWith("postgres://") && !value.startsWith("postgresql://")) {
    51	            return new JdbcUrl("jdbc:" + value, null, null);
    52	        }
    53	        URI uri = URI.create(value);
    54	        String user = null;
    55	        String password = null;
    56	        if (uri.getRawUserInfo() != null) {
    57	            String[] parts = uri.getRawUserInfo().split(":", 2);
    58	            user = decode(parts[0]);
    59	            password = parts.length > 1 ? decode(parts[1]) : null;
    60	        }
    61	        String port = uri.getPort() == -1 ? "" : ":" + uri.getPort();
    62	        String path = uri.getRawPath() == null ? "" : uri.getRawPath();
    63	        String query = uri.getRawQuery() == null ? "" : "?" + uri.getRawQuery();
    64	        return new JdbcUrl("jdbc:postgresql://" + uri.getHost() + port + path + query, user, password);
    65	    }
    66	
    67	    private static String decode(String value) {
    68	        return URLDecoder.decode(value, StandardCharsets.UTF_8);
    69	    }
