    62	        String path = uri.getRawPath() == null ? "" : uri.getRawPath();
    63	        String query = uri.getRawQuery() == null ? "" : "?" + uri.getRawQuery();
    64	        return new JdbcUrl("jdbc:postgresql://" + uri.getHost() + port + path + query, user, password);
